// Hand-written. Not generated by Speakeasy.
package functions

import (
	"encoding/base64"
	"strings"
	"testing"
)

func TestSecretBecomesAnOctKey(t *testing.T) {
	secret := strings.Repeat("a", 32)

	jwk, err := jwkFromSecret(secret, "hmac-1", "HS256", "sig")
	if err != nil {
		t.Fatal(err)
	}

	if jwk["kty"] != "oct" {
		t.Errorf("kty = %q, want oct", jwk["kty"])
	}
	if jwk["kid"] != "hmac-1" || jwk["alg"] != "HS256" || jwk["use"] != "sig" {
		t.Errorf("metadata not carried through: %v", jwk)
	}
	got, err := base64.RawURLEncoding.DecodeString(jwk["k"])
	if err != nil {
		t.Fatalf("k is not unpadded base64url: %v", err)
	}
	if string(got) != secret {
		t.Errorf("secret does not round-trip: %q", got)
	}
}

// The reason this function exists. Terraform has no base64urlencode, so the
// alternative is a chain of replace() calls on base64encode.
func TestKIsBase64urlWithoutPadding(t *testing.T) {
	// 32 bytes, so standard base64 pads, and the leading bytes encode to the
	// two characters where the alphabets differ: 0x3e and 0x3f are + and /
	// in standard base64, - and _ in base64url.
	secret := string([]byte{0xfb, 0xef, 0xbe}) + strings.Repeat("x", 29)

	jwk, err := jwkFromSecret(secret, "k", "HS256", "sig")
	if err != nil {
		t.Fatal(err)
	}

	// Assert the input actually exercises the difference, so the test cannot
	// pass by picking a secret that encodes the same either way.
	std := base64.StdEncoding.EncodeToString([]byte(secret))
	if !strings.ContainsAny(std, "+/=") {
		t.Fatalf("test secret does not exercise the alphabet difference: %s", std)
	}

	for _, bad := range []string{"+", "/", "="} {
		if strings.Contains(jwk["k"], bad) {
			t.Errorf("k contains %q, so it is standard base64 not base64url: %s", bad, jwk["k"])
		}
	}
}

func TestSecretAlgMustSuitASharedSecret(t *testing.T) {
	long := strings.Repeat("a", 64)

	for name, tc := range map[string]struct{ alg, use, wants string }{
		"an asymmetric signing alg":             {"RS256", "sig", "public and private"},
		"an asymmetric encryption alg":          {"RSA-OAEP", "enc", "public and private"},
		"EdDSA":                                 {"EdDSA", "sig", "public and private"},
		"a signing alg declared for encryption": {"HS256", "enc", "must be one of"},
		"a key wrap alg declared for signing":   {"A256KW", "sig", "must be one of"},
		"empty":                                 {"", "sig", "alg is empty"},
		"nonsense":                              {"NOPE", "sig", "does not match"},
	} {
		t.Run(name, func(t *testing.T) {
			_, err := jwkFromSecret(long, "k", tc.alg, tc.use)
			if err == nil {
				t.Fatalf("accepted alg %q for use %q", tc.alg, tc.use)
			}
			if !strings.Contains(err.Error(), tc.wants) {
				t.Errorf("error does not explain: %s", err)
			}
		})
	}
}

// A secret too short for its algorithm is accepted by Authlete, which stores
// the JWK Set without inspecting it, and then fails when it comes to sign.
func TestSecretLengthIsChecked(t *testing.T) {
	for name, tc := range map[string]struct {
		secret string
		alg    string
		use    string
		ok     bool
	}{
		"HS256 with 31 bytes":  {strings.Repeat("a", 31), "HS256", "sig", false},
		"HS256 with 32 bytes":  {strings.Repeat("a", 32), "HS256", "sig", true},
		"HS256 with 64 bytes":  {strings.Repeat("a", 64), "HS256", "sig", true},
		"HS384 with 32 bytes":  {strings.Repeat("a", 32), "HS384", "sig", false},
		"HS512 with 64 bytes":  {strings.Repeat("a", 64), "HS512", "sig", true},
		"A128KW with 16 bytes": {strings.Repeat("a", 16), "A128KW", "enc", true},
		"A128KW with 32 bytes": {strings.Repeat("a", 32), "A128KW", "enc", false},
		"A256KW with 32 bytes": {strings.Repeat("a", 32), "A256KW", "enc", true},
		// dir takes its size from the content encryption algorithm, which
		// this function never sees, so there is nothing to check.
		"dir with an odd length": {strings.Repeat("a", 7), "dir", "enc", true},
	} {
		t.Run(name, func(t *testing.T) {
			_, err := jwkFromSecret(tc.secret, "k", tc.alg, tc.use)
			if tc.ok && err != nil {
				t.Errorf("refused a valid key: %v", err)
			}
			if !tc.ok && err == nil {
				t.Errorf("accepted a %d-byte secret for %s", len(tc.secret), tc.alg)
			}
		})
	}
}

func TestSecretKidAndUseAreChecked(t *testing.T) {
	long := strings.Repeat("a", 32)

	if _, err := jwkFromSecret(long, "  ", "HS256", "sig"); err == nil {
		t.Error("accepted a blank kid")
	}
	if _, err := jwkFromSecret(long, "k", "HS256", "bogus"); err == nil {
		t.Error("accepted a use that is neither sig nor enc")
	}
	if _, err := jwkFromSecret("", "k", "HS256", "sig"); err == nil {
		t.Error("accepted an empty secret")
	}
}
